from bisect import bisect_left


class QuotaEngine:
    def __init__(self, policies: list[dict], allow_users: list[str] = ()):
        self.policies = list(policies)
        self.allow_users = set(allow_users) if allow_users is not None else set()
        self._buckets = {}

    def request(self, t_ms: int, attrs: dict, cost: int = 1) -> dict:
        if attrs["user"] in self.allow_users:
            return {
                "allowed": True,
                "retry_after_ms": 0,
                "limited_by": None,
                "remaining": {},
            }

        route = attrs["route"]
        evals = []

        for pol in self.policies:
            routes = pol.get("routes")
            if routes is not None:
                matched = False
                for prefix in routes:
                    if route.startswith(prefix):
                        matched = True
                        break
                if not matched:
                    continue

            per = pol["per"]
            key = None if per == "global" else attrs[per]

            overrides = pol.get("overrides")
            if overrides is not None and key is not None and key in overrides:
                limit = overrides[key]
            else:
                limit = pol["limit"]

            buckets = self._buckets.setdefault(pol["name"], {})
            kind = pol["kind"]
            charge_denied = pol.get("charge_denied", False)

            if kind == "token":
                rate = pol["rate"]
                cap = limit * 1000
                st = buckets.get(key)

                if st is None:
                    held = cap
                else:
                    held = st[0]
                    delta = t_ms - st[1]
                    if delta > 0:
                        held += delta * rate
                    if held > cap:
                        held = cap

                st = [held, t_ms]
                buckets[key] = st

                need_milli = cost * 1000
                if cost > limit:
                    accepted = False
                    retry = None
                elif held >= need_milli:
                    accepted = True
                    retry = 0
                else:
                    accepted = False
                    retry = (need_milli - held + rate - 1) // rate

                evals.append({
                    "name": pol["name"],
                    "kind": kind,
                    "st": st,
                    "limit": limit,
                    "accepted": accepted,
                    "retry": retry,
                    "charge_denied": charge_denied,
                })

            elif kind == "fixed":
                window_ms = pol["window_ms"]
                index = t_ms // window_ms
                st = buckets.get(key)

                if st is None or st[0] != index:
                    st = [index, 0]
                buckets[key] = st

                used = st[1]
                if cost > limit:
                    accepted = False
                    retry = None
                elif used + cost <= limit:
                    accepted = True
                    retry = 0
                else:
                    accepted = False
                    retry = (index + 1) * window_ms - t_ms

                evals.append({
                    "name": pol["name"],
                    "kind": kind,
                    "st": st,
                    "limit": limit,
                    "accepted": accepted,
                    "retry": retry,
                    "charge_denied": charge_denied,
                })

            else:  # sliding
                window_ms = pol["window_ms"]
                st = buckets.get(key)

                if st is None:
                    st = {
                        "entries": [],
                        "head": 0,
                        "prefix": [0],
                        "total": 0,
                    }
                    buckets[key] = st

                entries = st["entries"]
                head = st["head"]
                prefix = st["prefix"]
                total = st["total"]

                cutoff = t_ms - window_ms
                if head < len(entries) and entries[head][0] <= cutoff:
                    while head < len(entries) and entries[head][0] <= cutoff:
                        total -= entries[head][1]
                        head += 1

                if head > 0 and (head >= 1024 or head * 2 > len(entries)):
                    entries = entries[head:]
                    head = 0
                    prefix = [0]
                    s = 0
                    for _, c in entries:
                        s += c
                        prefix.append(s)
                    total = s

                st["entries"] = entries
                st["head"] = head
                st["prefix"] = prefix
                st["total"] = total

                if cost > limit:
                    accepted = False
                    retry = None
                elif total + cost <= limit:
                    accepted = True
                    retry = 0
                else:
                    accepted = False
                    target = limit - cost
                    need = prefix[-1] - target
                    k = bisect_left(prefix, need, head + 1, len(prefix))
                    retry = entries[k - 1][0] + window_ms - t_ms

                evals.append({
                    "name": pol["name"],
                    "kind": kind,
                    "st": st,
                    "limit": limit,
                    "accepted": accepted,
                    "retry": retry,
                    "charge_denied": charge_denied,
                })

        allowed = True
        for e in evals:
            if not e["accepted"]:
                allowed = False
                break

        best_name = None
        best_retry = None
        if not allowed:
            for e in evals:
                if e["accepted"]:
                    continue

                retry = e["retry"]
                if best_name is None:
                    best_name = e["name"]
                    best_retry = retry
                elif retry is None and best_retry is not None:
                    best_name = e["name"]
                    best_retry = retry
                elif retry is not None and best_retry is not None and retry > best_retry:
                    best_name = e["name"]
                    best_retry = retry

        remaining = {}
        for e in evals:
            kind = e["kind"]
            st = e["st"]
            limit = e["limit"]

            if allowed or e["charge_denied"]:
                if kind == "token":
                    milli = cost * 1000
                    if e["accepted"]:
                        st[0] -= milli
                    else:
                        sub = milli if milli <= st[0] else st[0]
                        st[0] -= sub
                elif kind == "fixed":
                    st[1] += cost
                else:
                    st["total"] += cost
                    st["entries"].append((t_ms, cost))
                    st["prefix"].append(st["prefix"][-1] + cost)

            if kind == "token":
                remaining[e["name"]] = st[0] // 1000
            elif kind == "fixed":
                rem = limit - st[1]
                remaining[e["name"]] = rem if rem >= 0 else 0
            else:
                rem = limit - st["total"]
                remaining[e["name"]] = rem if rem >= 0 else 0

        if allowed:
            return {
                "allowed": True,
                "retry_after_ms": 0,
                "limited_by": None,
                "remaining": remaining,
            }

        return {
            "allowed": False,
            "retry_after_ms": best_retry,
            "limited_by": best_name,
            "remaining": remaining,
        }
